input:
{
  "title": "Input schema for the empty project actor.",
  "description": "This scraper will get post and page details from Facebook pages of your choice. To try it out, just paste a Facebook Page URL and click ▷ Start. If you need any guidance, just <a href='https://blog.apify.com/scrape-facebook-posts-data/' target='_blank' rel='noopener'>follow this tutorial</a>.",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "startUrls": {
      "title": "Facebook URLs",
      "type": "array",
      "description": "Enter a valid Facebook page URL, e.g. <code>https://www.facebook.com/humansofnewyork/</code>. Note that you can only scrape public pages with this Actor, not personal profiles.",
      "editor": "requestListSources",
      "prefill": [
        {
          "url": "https://www.facebook.com/humansofnewyork/"
        }
      ],
      "example": [
        {
          "url": "https://www.facebook.com/humansofnewyork/"
        }
      ]
    },
    "resultsLimit": {
      "title": "Results amount",
      "type": "integer",
      "description": "Set how many posts should be scraped per page. For example, if set to 5, the scraper will extract up to 5 posts from each page. This setting is ignored when scraping direct post URLs. If this limit is not set, as many results as possible are returned.",
      "editor": "number",
      "prefill": 20,
      "minimum": 1,
      "example": 20
    },
    "captionText": {
      "title": "Include video transcript",
      "description": "Extract video transcript (if available).",
      "default": false,
      "type": "boolean",
      "editor": "checkbox",
      "example": false
    },
    "onlyPostsNewerThan": {
      "title": "Posts newer than",
      "type": "string",
      "description": "Scrape posts from the provided date to the present day (or date set in 'Older than'). The date should be in YYYY-MM-DD absolute format or in relative format, e.g., 1 day, 2 months, 3 years. The JSON input also supports adding time units (UTC timezone): Full or partial ISO timestamp (e.g., `2025-09-23T10:02:01`) as absolute time and relative time, e.g., `1 hour` or `2 minutes`.",
      "dateType": "absoluteOrRelative",
      "editor": "datepicker",
      "sectionCaption": "Time frame",
      "sectionDescription": "Use this if you only want to scrape posts from a specific period of time.",
      "pattern": "^(\\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])(T[0-2]\\d:[0-5]\\d(:[0-5]\\d)?(\\.\\d+)?Z?)?$|^(\\d+)\\s*(minute|hour|day|week|month|year)s?$",
      "example": "2024-01-01"
    },
    "onlyPostsOlderThan": {
      "title": "Posts older than",
      "type": "string",
      "description": "Scrape posts from the provided date to the past (or date set in 'Newer than'). The date should be in YYYY-MM-DD or full ISO absolute format or in relative format e.g. 1 days, 2 months, 3 years. The JSON input also supports adding time units (UTC timezone): Full or partial ISO timestamp (e.g., `2025-09-23T10:02:01`) as absolute time and relative time, e.g., `1 hour` or `2 minutes`.\n\n",
      "dateType": "absoluteOrRelative",
      "editor": "datepicker",
      "pattern": "^(\\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])(T[0-2]\\d:[0-5]\\d(:[0-5]\\d)?(\\.\\d+)?Z?)?$|^(\\d+)\\s*(minute|hour|day|week|month|year)s?$",
      "example": "2024-12-31"
    }
  },
  "required": [
    "startUrls"
  ]
}
